access._audit.source:
def _audit(self, event, category, target, store_id=False, before=None, after=None,
           result='accepted', reason=False, source='interactive'):
    return self.env['ydental.access.audit'].sudo().create(self._audit_values(
        event, category, target, store_id, before, after, result, reason, source,
    ))

access._audit_values.source:
def _audit_values(self, event, category, target, store_id=False, before=None, after=None,
                  result='accepted', reason=False, source='interactive'):
    """Private preparation, containing only documented nonsensitive metadata."""
    return {
        'ydental_user_id': self.env.uid, 'ydental_store_id': store_id,
        'ydental_event': event, 'ydental_category': category,
        'ydental_target_model': target._name, 'ydental_target_id': target.id,
        'ydental_result': result, 'ydental_reason': reason,
        'ydental_before': before, 'ydental_after': after, 'ydental_source': source,
    }

access._check.source:
def _check(self, category, level='read', store_id=None, write=False):
    if category not in dict(CATEGORIES) or level not in RANK:
        raise AccessError(self.env._('access_denied: Invalid authorization action.'))
    session = self._scope(write=write)
    store_id = store_id or session.ydental_store_id.id
    if not store_id or not self.env['ydental.access.store'].sudo().browse(store_id).active:
        raise AccessError(self.env._('access_denied: Select an active store.'))
    membership = self._membership(self.env.uid, store_id)
    if not membership or not membership.ydental_employee_id.active:
        raise AccessError(self.env._('access_denied: Active store membership is required.'))
    if RANK[self._levels(membership)[category]] < RANK[level]:
        raise AccessError(self.env._('access_denied: This business permission is required.'))
    if write and self._get_execution_store_id() not in (False, store_id):
        raise AccessError(self.env._('access_denied: Execution in another store blocks manual writes.'))
    return membership

access._membership.source:
def _membership(self, user_id, store_id, active=True):
    domain = [('ydental_user_id', '=', user_id), ('ydental_store_id', '=', store_id)]
    if active:
        domain.append(('active', '=', True))
    return self.env['ydental.access.membership'].sudo().with_context(active_test=False).search(domain, limit=1)

access._scope.source:
def _scope(self, write=False):
    self._require_internal()
    binding = self.env.context.get('ydental_binding')
    if not isinstance(binding, Binding) or binding.user_id != self.env.uid:
        self._denial('scope')
        raise AccessError(self.env._('access_denied: A server-bound login scope is required.'))
    session = self.env['ydental.access.session'].sudo().browse(binding.session_id).exists()
    if write:
        # Transaction lock closes the old-tab/switch race. A retry rebinds.
        self.env.cr.execute('SELECT id FROM ydental_access_session WHERE id=%s FOR UPDATE', [session.id])
        session.invalidate_recordset()
    if not session or session.ydental_user_id.id != self.env.uid:
        raise AccessError(self.env._('access_denied: Invalid login scope.'))
    if session.ydental_revision != binding.revision:
        raise UserError(self.env._('version_conflict: The store changed. Refresh this page.'))
    return session

clinical._access.source:
def _access(self, write=False):
    store = self.env['ydental.access.service']._check('medical', 'write' if write else 'read', write=write).ydental_store_id
    if store.company_id not in self.env.user.sudo().company_ids:
        raise AccessError(self.env._('access_denied: The current store company is outside this account\'s allowed companies.'))
    return store

clinical._acquire.source:
def _acquire(self, document_id, lease_id=None, lease_token=None):
    doc = self._document(document_id, True)
    queue = self._queue()
    session, connection = queue._connection()
    execution = doc.ydental_current_execution_id
    if execution.state in ('serving', 'reserved', 'verify'):
        lease = queue._held(lease_id, lease_token)
        if execution.state == 'verify' or execution.ydental_lease_id != lease or lease.ydental_expires_at <= queue._now():
            raise AccessError(self.env._('access_denied: The current reception holder must edit this document.'))
    else:
        lease = queue._model('lease')
        if doc.ydental_responsible_id.id != self.env.uid or not self._eligible_responsible(doc, self.env.user.sudo()):
            raise AccessError(self.env._('access_denied: Only the authorized responsible person may complete this document.'))
    if self._valid_editor(doc):
        raise UserError(self.env._('editor_busy: This independent document already has a connected editor.'))
    if doc.ydental_editor_id:
        self._audit('editor_invalidated', doc, after={'previous_editor_id': doc.ydental_editor_id.id})
    token = secrets.token_urlsafe(32)
    doc._save({'ydental_editor_id': self.env.uid, 'ydental_session_id': session.id,
        'ydental_session_revision': session.ydental_revision, 'ydental_connection_hash': connection.key_hash,
        'ydental_editor_hash': digest(token), 'ydental_editor_lease_id': lease.id,
        'ydental_editor_expires': queue._now() + timedelta(seconds=queue._settings()[1])})
    self._audit('edit_acquire', doc)
    return self._snapshot(doc) | {'editor_token': token}

clinical._append.source:
def _append(self, doc, expected_version, content, key, kind, reason=''):
    if type(expected_version) is not int or expected_version < 0 or not isinstance(key, str) or not 16 <= len(key) <= 128:
        raise ValidationError(self.env._('invalid_version: Supply a server version and stable request key.'))
    content = self._content(content)
    signature = digest(json.dumps([expected_version, content, kind, reason], sort_keys=True, ensure_ascii=False))
    versions = self._model('version')
    prior = versions.search([('ydental_document_id', '=', doc.id), ('ydental_request_key', '=', key)], limit=1)
    if prior:
        if prior.ydental_request_digest != signature or prior.ydental_author_id.id != self.env.uid:
            raise UserError(self.env._('version_conflict: This request key belongs to different content.'))
        return self._snapshot(doc) | {'saved_version': prior.ydental_number, 'duplicate': True}
    if doc.ydental_version != expected_version:
        raise UserError(self.env._('version_conflict: Refresh before editing a newer clinical version.'))
    if (kind in ('save', 'confirm') and doc.state == 'confirmed') or (kind == 'correct' and doc.state != 'confirmed'):
        raise UserError(self.env._('correction_required: Confirmed text requires a new correction and reason.'))
    if kind in ('confirm', 'correct') and not any(content[name].strip() for name in TEXT_FIELDS) and not content['teeth']:
        raise ValidationError(self.env._('content_required: Empty clinical text cannot be confirmed.'))
    previous = versions.search([('ydental_document_id', '=', doc.id)], order='ydental_number desc', limit=1)
    now = self._queue()._now()
    version = versions._new({'ydental_store_id': doc.ydental_store_id.id, 'ydental_document_id': doc.id,
        'ydental_patient_id': doc.ydental_patient_id.id, 'ydental_number': expected_version + 1,
        'ydental_content': content, 'ydental_author_id': self.env.uid, 'ydental_recorded_at': now,
        'ydental_kind': kind, 'ydental_reason': reason, 'ydental_previous_id': previous.id,
        'ydental_request_key': key, 'ydental_request_digest': signature, 'ydental_template': doc.ydental_template})
    doc._save({'ydental_version': version.ydental_number, 'ydental_content': content, 'ydental_saved_at': now,
               **({'state': 'confirmed'} if kind in ('confirm', 'correct') else {})})
    self._audit(kind, doc, before={'version': expected_version}, after={'version': version.ydental_number}, reason=reason)
    return self._snapshot(doc) | {'saved_version': version.ydental_number}

clinical._audit.source:
def _audit(self, event, doc, before=None, after=None, reason=False):
    access = self.env['ydental.access.service']
    return access._audit('clinical.' + event, 'medical', doc, access._scope().ydental_store_id.id,
                         before=before, after=after, reason=reason, source='clinical_document')

clinical._confirm.source:
def _confirm(self, document_id, editor_token, expected_version, content, key):
    doc = self._held(document_id, editor_token)
    return self._append(doc, expected_version, content, key, 'confirm')

clinical._content.source:
def _content(self, content):
    if not isinstance(content, dict) or set(content) != set(TEXT_FIELDS) | {'teeth'}:
        raise ValidationError(self.env._('invalid_content: Submit the complete clinical draft field set.'))
    result = {}
    for name in TEXT_FIELDS:
        text = content[name]
        if not isinstance(text, str) or len(text) > 10000:
            raise ValidationError(self.env._('invalid_content: Clinical text exceeds its allowed size.'))
        result[name] = text
    teeth = content['teeth']
    if not isinstance(teeth, list) or len(teeth) > 53:
        raise ValidationError(self.env._('invalid_tooth: Invalid FDI tooth collection.'))
    seen = set()
    rows = []
    for row in teeth:
        if not isinstance(row, dict) or set(row) != {'tooth', 'state', 'surfaces'}:
            raise ValidationError(self.env._('invalid_tooth: Supply tooth, state and surfaces.'))
        tooth, state, surfaces = row['tooth'], row['state'], row['surfaces']
        if type(tooth) is not int or tooth not in (0,) + TEETH or tooth in seen or state not in ('present', 'missing', 'unknown', 'not_applicable'):
            raise ValidationError(self.env._('invalid_tooth: Select a valid distinct FDI tooth and explicit state.'))
        if not isinstance(surfaces, list) or any(not isinstance(s, str) for s in surfaces) or len(set(surfaces)) != len(surfaces):
            raise ValidationError(self.env._('invalid_surface: Select distinct legal tooth surfaces.'))
        allowed = {'M', 'D', 'B', 'L', 'I' if tooth % 10 <= 3 else 'O'}
        if (tooth == 0 and state != 'not_applicable') or (tooth != 0 and state == 'not_applicable') or (state != 'present' and surfaces) or not set(surfaces) <= allowed:
            raise ValidationError(self.env._('invalid_surface: Surfaces must match the tooth and its recorded state.'))
        seen.add(tooth)
        rows.append({'tooth': tooth, 'state': state, 'surfaces': sorted(surfaces)})
    result['teeth'] = sorted(rows, key=lambda row: row['tooth'])
    return result

clinical._correct.source:
def _correct(self, document_id, editor_token, expected_version, content, key, reason):
    reason = self.env['ydental.intake.service']._text(reason)
    return self._append(self._held(document_id, editor_token), expected_version, content, key, 'correct', reason)

clinical._document.source:
def _document(self, document_id, write=False):
    store = self._access(write)
    doc = self._model().browse(self.env['ydental.intake.service']._id(document_id)).exists()
    if not doc:
        raise AccessError(self.env._('access_denied: This clinical document is unavailable.'))
    if write and doc.ydental_store_id != store:
        raise AccessError(self.env._('access_denied: Write clinical text only in its source store.'))
    if not write:
        self.env['ydental.clinical.document'].browse(doc.id).check_access('read')
    self.env['ydental.patient.service']._current_relation(doc.ydental_patient_id, store)
    return doc

clinical._heartbeat.source:
def _heartbeat(self, document_id, editor_token):
    doc = self._held(document_id, editor_token)
    doc._save({'ydental_editor_expires': self._queue()._now() + timedelta(seconds=self._queue()._settings()[1])})
    return {'document_id': doc.id, 'version': doc.ydental_version}

clinical._held.source:
def _held(self, document_id, editor_token):
    doc = self._document(document_id, True)
    session, connection = self._queue()._connection()
    if not self._valid_editor(doc) or doc.ydental_editor_id.id != self.env.uid or doc.ydental_session_id != session or not consteq(doc.ydental_connection_hash, connection.key_hash) or not isinstance(editor_token, str) or len(editor_token) > 128 or not consteq(doc.ydental_editor_hash, digest(editor_token)):
        raise AccessError(self.env._('editor_expired: This connection no longer holds the document.'))
    return doc

clinical._operate.source:
def _operate(self, operation, payload):
    handlers = {'open': self._open, 'acquire': self._acquire, 'heartbeat': self._heartbeat,
                'release': self._release, 'save': self._save, 'confirm': self._confirm,
                'correct': self._correct, 'handover': self._handover, 'transfer': self._transfer}
    if operation not in handlers or not isinstance(payload, dict):
        raise ValidationError(self.env._('invalid_action: Unknown clinical document action.'))
    try:
        inspect.signature(handlers[operation]).bind(**payload)
    except TypeError as error:
        raise ValidationError(self.env._('invalid_action: Unknown or missing clinical arguments.')) from error
    self._access(write=True)
    self._queue()._connection()
    with self.env.cr.savepoint():
        # Preserve S06 lock order. The common queue fence also serializes CAS,
        # document locks and handover with patient/permission transactions.
        self._queue()._locks()
        self._access(write=True)
        return handlers[operation](**payload) | {'result': 'accepted'}

clinical._read.source:
def _read(self, document_id, purpose=None):
    if purpose:
        preliminary = self._model().browse(self.env['ydental.intake.service']._id(document_id)).exists()
        if not preliminary:
            raise AccessError(self.env._('access_denied: This clinical document is unavailable.'))
        self = self.env['ydental.access.service']._patient_care(preliminary.ydental_patient_id.id, purpose).env[self._name]
    doc = self._document(document_id)
    self._audit('view', doc)
    return self._snapshot(doc)

clinical._release.source:
def _release(self, document_id, editor_token):
    doc = self._held(document_id, editor_token)
    self._clear_editor(doc)
    self._audit('edit_release', doc)
    return {'document_id': doc.id}

clinical._snapshot.source:
def _snapshot(self, doc):
    return {'document_id': doc.id, 'execution_id': doc.ydental_current_execution_id.id, 'source_execution_id': doc.ydental_execution_id.id, 'version': doc.ydental_version,
        'state': doc.state, 'content': doc.ydental_content, 'template': doc.ydental_template,
        'saved_at': fields.Datetime.to_string(doc.ydental_saved_at) if doc.ydental_saved_at else False,
        'responsible_id': doc.ydental_responsible_id.id}

exam._confirm.source:
def _confirm(self, line_id, version, reason):
    line = self._line(line_id, write=True)
    result = self._result(line)
    if not result or not result.ydental_event_id or result.state not in ('pending', 'partial') or not result.ydental_findings:
        raise UserError(self.env._('result_required: Actual execution and reviewed findings are required.'))
    self._editor(result, version)
    reason = self.env['ydental.intake.service']._text(reason)
    result._save({'state': 'confirmed', 'ydental_completed_at': fields.Datetime.now(), 'ydental_version': version + 1})
    self._version(result, 'confirm', reason)
    return {'result_id': result.id, 'version': result.ydental_version, 'state': result.state}

exam._operate.source:
def _operate(self, operation, payload, key):
    handlers = {'grant_qualification': self._grant_qualification,
        'review_capability': self._review_capability,
        'bind_template': self._bind_template, 'revalidate': self._revalidate,
        'release_editor': self._release_editor, 'takeover': self._takeover,
        'draft': self._draft,
        'perform': self._perform, 'confirm': self._confirm, 'correct': self._correct,
        'abort': self._abort, 'finish': self._finish, 'reconcile': self._reconcile,
        'verify_materials': self._verify_materials,
        'attach': self._attachment}
    if operation not in handlers or not isinstance(payload, dict) or not isinstance(key, str) or not 1 <= len(key) <= 120:
        raise ValidationError(self.env._('invalid_action: Select a documented examination action and stable key.'))
    try:
        inspect.signature(handlers[operation]).bind(**payload)
    except TypeError as error:
        raise ValidationError(self.env._('invalid_action: Unknown or missing examination arguments.')) from error
    queue = self.env['ydental.queue.service']
    if operation not in ('grant_qualification', 'bind_template', 'review_capability'):
        if operation == 'revalidate':
            self.env['ydental.access.service']._check('medical', 'write', write=True)
        else:
            self._store(write=True)
        queue._connection()
    digest = fingerprint([operation, payload])
    with self.env.cr.savepoint():
        queue._locks()
        self.env['ydental.inventory.service']._lock()
        self.env.cr.execute('SELECT pg_advisory_xact_lock(%s)', [32008])
        self.env.cr.execute('SELECT pg_advisory_xact_lock(%s)', [33009])
        if operation not in ('grant_qualification', 'bind_template', 'review_capability'):
            if operation == 'revalidate':
                self.env['ydental.access.service']._check('medical', 'write', write=True)
            else:
                self._store(write=True)
            queue._connection()
        prior = self._model('receipt').search([('ydental_actor_id', '=', self.env.uid), ('ydental_key', '=', key)], limit=1)
        if prior:
            if prior.ydental_fingerprint != digest:
                raise UserError(self.env._('version_conflict: This examination key belongs to another action.'))
            return dict(prior.ydental_result, result='already_accepted')
        response = handlers[operation](**payload)
        store = self.env['ydental.access.service']._scope().ydental_store_id
        self._model('receipt')._new({'name': operation, 'ydental_store_id': store.id, 'ydental_category': 'exam',
            'ydental_patient_id': False, 'ydental_actor_id': self.env.uid,
            'ydental_key': key, 'ydental_fingerprint': digest, 'ydental_result': response})
        return dict(response, result='accepted')

exam._store.source:
def _store(self, write=False):
    access = self.env['ydental.access.service']
    level = 'write' if write else 'read'
    try:
        member = access._check('exam', level, write=write)
    except AccessError:
        if write:
            raise
        member = access._check('medical', 'read')
    store = member.ydental_store_id
    if store.company_id not in self.env.user.sudo().company_ids:
        raise AccessError(self.env._('access_denied: The source company is outside the account scope.'))
    return store

inventory._return.source:
def _return(self, store, event_id, quantity, uom_id, source_key, reason):
    parent = self._get('event', event_id, store)
    if parent.state != 'done' or parent.ydental_kind not in ('replenishment', 'prescription'):
        raise UserError(self.env._('return_invalid: Select an actual completed issue.'))
    lot = parent.ydental_lot_id; config = self._config(store)
    qty, unit, snap = self._unit(lot.product_id, quantity, uom_id)
    prior = self._model('event').search([('ydental_parent_id', '=', parent.id), ('ydental_kind', '=', 'return'), ('ydental_source_key', '!=', source_key)])
    if lot.product_id.uom_id.compare(sum(prior.mapped('ydental_quantity')) + qty, parent.ydental_quantity) > 0:
        raise UserError(self.env._('return_limit: Physical returns cannot exceed the actual issue.'))
    event = self._event(store, 'warehouse', source_key, 'return', lot, quantity, uom_id,
        config.ydental_customer_id, config.ydental_quarantine_id, reason, parent=parent)
    return {'id': event.id, 'move_id': event.ydental_move_id.id, 'state': 'quarantine'}

inventory._verify.source:
def _verify(self, store, event_id, quantity, uom_id, disposition, source_key, reason):
    parent = self._get('event', event_id, store)
    if parent.ydental_kind != 'return' or parent.state != 'done' or disposition not in ('release', 'discard'):
        raise ValidationError(self.env._('Select a physical return and its verified destination.'))
    lot = parent.ydental_lot_id; config = self._config(store)
    if disposition == 'release':
        self._usable(lot, store)
    qty, unit, snap = self._unit(lot.product_id, quantity, uom_id)
    done = self._model('event').search([('ydental_parent_id', '=', parent.id), ('ydental_kind', '=', 'verification'), ('ydental_source_key', '!=', source_key)])
    if lot.product_id.uom_id.compare(sum(done.mapped('ydental_quantity')) + qty, parent.ydental_quantity) > 0:
        raise UserError(self.env._('return_limit: Verification exceeds the remaining physical return.'))
    event = self._event(store, 'warehouse', source_key, 'verification', lot, quantity, uom_id,
        config.ydental_quarantine_id, self._location(config, lot.product_id) if disposition == 'release' else config.ydental_loss_id,
        reason, parent=parent)
    return {'id': event.id, 'move_id': event.ydental_move_id.id, 'disposition': disposition}

print._deliver.source:
def _deliver(self, operation, job_id):
    if operation not in ('pdf_view', 'download', 'print_request'):
        raise ValidationError(self.env._('invalid_action: Select a documented PDF operation.'))
    job, source, category, payload, signature = self._job(job_id)
    pdf = job.ydental_pdf.content
    if hashlib.sha256(pdf).hexdigest() != job.ydental_pdf_digest:
        raise UserError(self.env._('render_failed: Temporary PDF integrity verification failed.'))
    self._audit('print_requested' if operation == 'print_request' else operation, source, category, payload, signature, job)
    return pdf, job.ydental_pdf_digest

print._generate.source:
def _generate(self, kind, source_id, version, expected_digest, key, purpose=None):
    if not isinstance(expected_digest, str) or not re.fullmatch('[a-f0-9]{64}', expected_digest) or not isinstance(key, str) or not 16 <= len(key) <= 128:
        raise ValidationError(self.env._('invalid_source: Review the source digest and supply a stable generation key.'))
    service, source, category, payload, signature = self._source(kind, source_id, version, purpose)
    if signature != expected_digest:
        raise UserError(self.env._('version_conflict: The source changed. Review before generating a PDF.'))
    session = self.env['ydental.access.service']._scope()
    jobs = self.env['ydental.print.job'].sudo()
    prior = jobs.search([('ydental_session_id', '=', session.id), ('ydental_revision', '=', session.ydental_revision), ('ydental_key', '=', key)], limit=1)
    if prior:
        job, _, _, _, _ = self._job(prior.id)
        if (job.ydental_kind, job.ydental_source_id, job.ydental_version, job.ydental_source_digest) != (kind, source_id, version, expected_digest):
            raise UserError(self.env._('version_conflict: This generation key belongs to another source.'))
        self._audit('generate_repeat', source, category, payload, signature, job)
    else:
        scope = service._render_scope(payload, signature, purpose)
        reports = service.env['ir.actions.report'].with_context(ydental_print_scope=scope, lang='zh_CN', force_report_rendering=True, report_pdf_no_attachment=True)
        try:
            pdf, output_type = reports._render_qweb_pdf(REPORT, [source.id])
            if output_type != 'pdf' or not isinstance(pdf, bytes) or not pdf.startswith(b'%PDF-') or len(pdf) > 10000000:
                raise UserError(self.env._('render_failed: The PDF engine did not produce a valid bounded PDF.'))
            if len(PdfFileReader(io.BytesIO(pdf)).pages) > 80:
                raise UserError(self.env._('size_limit: This PDF exceeds the demonstration page limit.'))
        except (QWebError, PdfReadError, OSError, ValueError) as error:
            raise UserError(self.env._('render_failed: The PDF engine did not produce a valid bounded PDF.')) from error
        job = jobs._new({'ydental_actor_id': self.env.uid, 'ydental_store_id': session.ydental_store_id.id,
            'ydental_session_id': session.id, 'ydental_revision': session.ydental_revision, 'ydental_kind': kind,
            'ydental_source_id': source_id, 'ydental_version': version, 'ydental_purpose': purpose,
            'ydental_source_digest': signature, 'ydental_pdf_digest': hashlib.sha256(pdf).hexdigest(),
            'ydental_template': TEMPLATES[kind], 'ydental_versions': payload['versions'],
            'ydental_expires_at': fields.Datetime.now() + timedelta(minutes=15), 'ydental_key': key,
            'ydental_pdf': BinaryBytes(pdf, filename='ydental-demonstration.pdf')})
        self._audit('generate', source, category, payload, signature, job)
    return {'job_id': job.id, 'pdf_digest': job.ydental_pdf_digest, 'source_digest': signature, 'versions': job.ydental_versions,
            'expires_at': str(job.ydental_expires_at), 'paper_output': 'unknown'}

queue._held.source:
def _held(self, lease_id, token, admission=False):
    session, connection = self._connection()
    lease = self._model('lease').browse(self.env['ydental.intake.service']._id(lease_id)).exists()
    if not lease or not lease.ydental_active or lease.ydental_actor_id.id != self.env.uid or (
        lease.ydental_session_id.id, lease.ydental_revision
    ) != (session.id, session.ydental_revision) or not consteq(lease.ydental_connection_hash, connection.key_hash) or (
        not isinstance(token, str) or len(token) > 128 or not consteq(lease.ydental_token_hash, digest(token))
    ):
        raise AccessError(self.env._('access_denied: This connection no longer holds the workstation.'))
    self._station(lease.ydental_station_id.id, admission=admission)
    return lease

queue._settings.source:
def _settings(self):
    params = self.env['ir.config_parameter'].sudo()
    try:
        heartbeat = int(params.get_str('ydental_queue.heartbeat_seconds', ''))
        timeout = int(params.get_str('ydental_queue.timeout_seconds', ''))
    except (ValueError, TypeError) as error:
        raise UserError(self.env._('configuration_required: Publish explicit heartbeat and timeout settings.')) from error
    if not 1 <= heartbeat < timeout <= 86400:
        raise UserError(self.env._('configuration_required: Timeout must exceed the positive heartbeat interval.'))
    return heartbeat, timeout

settlement._bill.source:
def _bill(self, fee_ids, discount, reason):
    store = self._access(write=True)
    config = self._config(store)
    if not isinstance(fee_ids, list) or not fee_ids or any(type(x) is not int for x in fee_ids) or len(set(fee_ids)) != len(fee_ids):
        raise ValidationError(self.env._('Select distinct confirmed fee sources.'))
    fees = [self._fee(fee_id, store) for fee_id in fee_ids]
    patient = self._patient(fees[0].ydental_patient_id.id)
    if any(not self._same_patient(fee, patient) for fee in fees):
        raise AccessError(self.env._('access_denied: Mixed patient fees cannot be billed.'))
    prior = self._model('source').search([('ydental_fee_id', 'in', fee_ids)])
    if prior:
        if len(prior) == len(fees) and not discount and len(prior.ydental_invoice_id) == 1:
            return {'invoice_id': prior.ydental_invoice_id.id, 'amount': prior.ydental_invoice_id.amount_total}
        raise UserError(self.env._('fee_already_billed: Source fees cannot be billed twice.'))
    if any(fee.ydental_amount < 0 for fee in fees):
        if len(fees) != 1 or fees[0].ydental_amount >= 0 or discount:
            raise UserError(self.env._('correction_separate: Bill each confirmed reversal against its original source.'))
        self._close_guard_any(store, self.env.uid, fees[0].ydental_event_id.ydental_business_date)
        return self._bill_correction(fees[0], store, config)
    currency = store.company_id.currency_id
    original = currency.round(sum(fee.ydental_amount for fee in fees))
    discount = self._money(discount, currency, allow_zero=True)
    if discount > original or discount and not self._text(reason):
        raise ValidationError(self.env._('Discount requires a reason and cannot exceed the selected fees.'))
    date = max(fee.ydental_event_id.ydental_business_date for fee in fees)
    for fee in fees:
        self._close_guard_any(store, self.env.uid, fee.ydental_event_id.ydental_business_date)
    commands = [Command.create({
        'name': fee.name,
        'quantity': fee.ydental_quantity,
        'price_unit': fee.ydental_unit_price,
        'account_id': config.ydental_income_account_id.id,
        'tax_ids': [Command.clear()],
        'product_id': fee.ydental_product_id.id or False,
    }) for fee in fees]
    if discount:
        commands.append(Command.create({
            'name': self.env._('Explicit demonstration discount: %s', self._text(reason)),
            'quantity': 1, 'price_unit': -discount,
            'account_id': config.ydental_income_account_id.id,
            'tax_ids': [Command.clear()],
        }))
    invoice = self.env['account.move'].sudo().with_company(store.company_id).create({
        'move_type': 'out_invoice', 'company_id': store.company_id.id,
        'journal_id': config.ydental_sales_journal_id.id,
        'partner_id': patient.ydental_partner_id.id,
        'invoice_date': date, 'date': date,
        'currency_id': currency.id,
        'invoice_origin': 'YDental confirmed fee sources ' + ','.join(map(str, fee_ids)),
        'invoice_line_ids': commands,
    })
    invoice.action_post()
    if invoice.state != 'posted' or currency.compare_amounts(invoice.amount_total, original - discount):
        raise UserError(self.env._('accounting_mismatch: Native invoice differs from frozen fees.'))
    lines = invoice.invoice_line_ids.sorted('id')[:len(fees)]
    if len(lines) != len(fees):
        raise UserError(self.env._('accounting_mismatch: Native source lines are incomplete.'))
    for fee, line in zip(fees, lines):
        if currency.compare_amounts(line.price_subtotal, fee.ydental_amount):
            raise UserError(self.env._('accounting_mismatch: Native source line differs from its frozen fee.'))
        snapshot = fee.ydental_price_snapshot_id
        version = 'S05:' + str(snapshot.ydental_price_id.id) if snapshot else 'review:' + str(fee.ydental_price_review_id.id)
        try:
            with self.env.cr.savepoint():
                self._model('source')._new({
                    'ydental_fee_id': fee.id, 'ydental_store_id': store.id,
                    'ydental_patient_id': fee.ydental_patient_id.id,
                    'ydental_invoice_id': invoice.id, 'ydental_line_id': line.id,
                    'ydental_original_amount': fee.ydental_amount, 'ydental_currency_id': currency.id,
                    'ydental_discount': discount if fee == fees[0] else 0,
                    'ydental_discount_reason': reason if discount and fee == fees[0] else False,
                    'ydental_source_business_date': fee.ydental_event_id.ydental_business_date,
                    'ydental_source_actual_at': fee.ydental_event_id.ydental_actual_at,
                    'ydental_price_version': version,
                })
        except UniqueViolation as error:
            if error.diag.constraint_name != 'ydental_settlement_source_fee_once':
                raise
            # A competing REPEATABLE READ transaction cannot see the winner's
            # new source. Abort this invoice instead of leaking a SQL error.
            raise UserError(self.env._('concurrent_bill: This fee was billed by another request. Refresh and review its invoice.')) from error
    self._audit('bill', invoice, store, after={'fee_ids': fee_ids, 'amount': invoice.amount_total,
                                               'discount': discount}, reason=reason)
    return {'invoice_id': invoice.id, 'amount': invoice.amount_total, 'residual': invoice.amount_residual}

settlement._close_guard.source:
def _close_guard(self, store, cashier_id, business_date, channel):
    closed = self._model('close').search([
        ('ydental_store_id', '=', store.id), ('ydental_cashier_id', '=', cashier_id),
        ('ydental_business_date', '=', business_date), ('ydental_channel', '=', channel),
    ], order='ydental_cycle desc', limit=1)
    if closed and closed.ydental_state == 'confirmed':
        raise UserError(self.env._('day_closed: A finance approver must unlock this cashier day.'))

settlement._close_guard_any.source:
def _close_guard_any(self, store, cashier_id, business_date):
    for channel in CHANNELS:
        self._close_guard(store, cashier_id, business_date, channel)

treatment._bookkeep.source:
def _bookkeep(self, event):
    if not event.ydental_already_performed:
        self._settle(event)
        return
    try:
        with self.env.cr.savepoint():
            self._settle(event)
    except (AccessError, ValidationError):
        raise
    except UserError as error:
        # A verified physical fact survives a known native business failure;
        # its economic savepoint rolls back every move and fee. Database
        # serialization/deadlock errors still reach the framework unchanged.
        event._save({'state': 'pending', 'ydental_pending_reason': 'bookkeeping_failed'})
        self._audit('bookkeeping_pending', event, {'failure_code': str(error).split(':')[0][:120]})

treatment._correct.source:
def _correct(self, event_id, execution_id, lease_id, lease_token, document_id, document_version,
             delta, source, reason, materials):
    execution, doc = self._medical(execution_id, lease_id, lease_token, document_id, document_version)
    parent = self._get('event', event_id, 'medical')
    if parent.ydental_patient_id != execution.ydental_patient_id or parent.ydental_kind not in ('treatment', 'chairside') or parent.state != 'confirmed':
        raise UserError(self.env._('correction_required: Select a confirmed treatment source for this patient.'))
    self._project(execution, parent.ydental_catalog_id.id)
    if parent.ydental_kind == 'chairside' and not parent.ydental_medicine_link_id:
        raise UserError(self.env._('medicine_evidence_missing: Historical medication needs a separately evidenced review before new corrections.'))
    if not (type(delta) in (int, float) and delta == 0 and materials):
        self._quantity(delta, parent.ydental_uom_id, signed=True)
    corrections = self._model('event').search([('ydental_parent_id', '=', parent.id)])
    prior = corrections.filtered(lambda e: e.ydental_source == source)
    net = parent.ydental_quantity + sum((corrections - prior).mapped('ydental_quantity')) + delta
    if net < 0 or delta < 0 and materials:
        raise ValidationError(self.env._('invalid_quantity: A correction cannot exceed the original quantity; physical returns require a separate verified return.'))
    return self._event(execution, parent.ydental_catalog_id, delta, source, reason, materials,
        doc=doc, teeth=parent.ydental_teeth, kind='correction', parent=parent)

treatment._event.source:
def _event(self, execution, catalog, quantity, source, reason, rows, *, doc=None, teeth=None,
           already_performed=False, kind='treatment', line=None, parent=None, actual_at=None, medicine_link=None, expected_product=None):
    if not isinstance(source, str) or not 1 <= len(source) <= 120 or type(already_performed) is not bool:
        raise ValidationError(self.env._('invalid_source: Supply a stable source identifier and explicit fact status.'))
    if not (kind == 'correction' and type(quantity) in (int, float) and quantity == 0 and rows):
        quantity = self._quantity(quantity, catalog.ydental_product_id.uom_id, signed=kind == 'correction')
    reason = self.env['ydental.intake.service']._text(reason)
    rows = self._material_rows(rows, execution.ydental_category, execution.ydental_store_id)
    if actual_at is not None and (not isinstance(actual_at, str) or len(actual_at) != 19):
        raise ValidationError(self.env._('invalid_time: Supply an explicit UTC date and time with seconds.'))
    moment = fields.Datetime.to_datetime(actual_at) if actual_at else fields.Datetime.now()
    if moment < execution.ydental_started_at or moment > fields.Datetime.now():
        raise ValidationError(self.env._('invalid_time: Actual time must fall within this started service and cannot be in the future.'))
    digest = fingerprint([actual_at, execution.id, catalog.id, quantity, reason, rows, doc.id if doc else False,
        doc.ydental_version if doc else 0, teeth, already_performed, kind, line.id if line else False, parent.id if parent else False])
    prior = self._model('event').search([('ydental_store_id', '=', execution.ydental_store_id.id), ('ydental_source', '=', source)], limit=1)
    if prior:
        if prior.ydental_fingerprint != digest or prior.ydental_actor_id.id != self.env.uid:
            raise UserError(self.env._('version_conflict: This clinical source already has immutable execution parameters.'))
        return self._event_result(prior)
    medication = kind in ('chairside', 'prescription') or bool(parent and parent.ydental_medicine_link_id)
    evidence_missing = False
    if medication:
        medicine_link = medicine_link or (parent.ydental_medicine_link_id if parent else self._medicine_link(execution.ydental_store_id, catalog=catalog, required=False))
        if expected_product and medicine_link and medicine_link.ydental_product_id != expected_product:
            medicine_link = self._model('medicine.link')
        try:
            self._check_medication(medicine_link, rows, quantity, expected_product, correction=bool(parent))
        except UserError:
            if not already_performed:
                raise
            evidence_missing = True
    event = self._new('event', execution, {'name': catalog.name, 'ydental_execution_id': execution.id,
        'ydental_document_id': doc.id if doc else False, 'ydental_document_version': doc.ydental_version if doc else 0,
        'ydental_order_line_id': line.id if line else False, 'ydental_source': source, 'ydental_fingerprint': digest,
        'ydental_kind': kind, 'ydental_catalog_id': catalog.id,
        'ydental_medicine_link_id': medicine_link.id if medicine_link else False,
        'ydental_product_id': expected_product.id if expected_product else medicine_link.ydental_product_id.id if medicine_link else False,
        'ydental_reported_materials': {'rows': rows, 'catalog_id': catalog.id}, 'ydental_quantity': quantity,
        'ydental_uom_id': catalog.ydental_product_id.uom_id.id, 'ydental_teeth': teeth,
        'ydental_actual_at': moment, 'ydental_business_date': self.env['ydental.supply.service']._date(execution.ydental_store_id, moment),
        'ydental_station_id': execution.ydental_lease_id.ydental_station_id.id, 'ydental_reason': reason,
        'ydental_already_performed': already_performed, 'ydental_parent_id': parent.id if parent else False})
    if parent:
        event._save({'ydental_price_snapshot_id': parent.ydental_price_snapshot_id.id,
            'ydental_price_review_id': parent.ydental_price_review_id.id})
    elif not medication or medicine_link:
        try:
            self._quote(event)
        except UserError as error:
            if not already_performed or not str(error).startswith('missing_price:'):
                raise
            event._save({'ydental_pending_reason': 'missing_price'})
    if evidence_missing:
        event._save({'ydental_pending_reason': 'medicine_evidence_missing'})
        rows = []
    for row in rows:
        self._new('consumption', event, {'name': source, 'ydental_event_id': event.id,
            'ydental_lot_id': row['lot_id'], 'ydental_quantity': row['quantity'],
            'ydental_uom_id': row['uom_id'], 'ydental_kind': row['kind']})
    self._bookkeep(event)
    self._audit('actual_execution', event, self._event_result(event), reason)
    return self._event_result(event)

treatment._medical.source:
def _medical(self, execution_id, lease_id, lease_token, document_id, document_version):
    execution = self._serving(execution_id, lease_id, lease_token, 'medical')
    doc = self.env['ydental.clinical.service']._document(document_id, write=True)
    if doc.ydental_current_execution_id != execution or type(document_version) is not int or doc.ydental_version != document_version or document_version < 1:
        raise UserError(self.env._('save_required: Save and verify the current document version before the clinical action.'))
    return execution, doc

treatment._price_values.source:
def _price_values(self, event):
    if event.ydental_price_snapshot_id:
        snap = event.ydental_price_snapshot_id
        return {'version': snap.ydental_price_id.id, 'currency': snap.ydental_currency_id.id,
            'unit_price': snap.ydental_unit_price, 'policy': 'demo_confirmation'}
    if event.ydental_price_review_id:
        review = event.ydental_price_review_id
        return {'version': 'review-' + str(review.id), 'currency': review.ydental_currency_id.id,
            'unit_price': review.ydental_unit_price, 'policy': 'demo_confirmation'}
    return None

treatment._remaining.source:
def _remaining(self, line):
    # Actual issue facts, including pending bookkeeping, consume the
    # approved allowance. Physical returns never reopen the prescription.
    events = self._model('event').search([('ydental_order_line_id', '=', line.id), ('ydental_kind', '=', 'prescription')])
    return line.ydental_quantity - sum(events.mapped('ydental_quantity'))
